code.cpp:
class Solution {
public:
    vector<int> findErrorNums(vector<int>& nums) {
        int dup = -1;
        for (int i = 0; i < (int)nums.size(); i++) {
            int idx = abs(nums[i]) - 1;
            if (nums[idx] < 0) {
                dup = abs(nums[i]);
            } else {
                nums[idx] = -nums[idx];
            }
        }
        int missing = -1;
        for (int i = 0; i < (int)nums.size(); i++) {
            if (nums[i] > 0) {
                missing = i + 1;
                break;
            }
        }
        return {dup, missing};
    }
};
